# ========================================# =============== 任务排程页 ===============# ========================================import osimport jsonimport timeimport schedimport threadingfrom datetime import datetime, timedeltafrom umi_log import loggerfrom .page import Page  # 页基类from ..mission.mission_ocr import MissionOCR  # 任务管理器from ..utils.utils import allowedFileNamefrom ..ocr.output import Output  # 输出器class TaskScheduler(Page):    def __init__(self, *args):        super().__init__(*args)        self.scheduler = sched.scheduler(time.time, time.sleep)        self.scheduled_tasks = {}  # 存储所有计划任务        self.task_logs = []  # 存储任务执行日志        self.load_tasks()        self.load_logs()        # 启动调度器线程        self.scheduler_thread = threading.Thread(target=self.scheduler.run, daemon=True)        self.scheduler_thread.start()    # ========================= 【任务管理】 =========================    def load_tasks(self):        """加载计划任务"""        try:            if os.path.exists("./config/task_scheduler_tasks.json"):                with open("./config/task_scheduler_tasks.json", "r", encoding="utf-8") as f:                    self.scheduled_tasks = json.load(f)        except Exception as e:            logger.error(f"加载计划任务失败: {e}", exc_info=True)    def save_tasks(self):        """保存计划任务"""        try:            os.makedirs("./config", exist_ok=True)            with open("./config/task_scheduler_tasks.json", "w", encoding="utf-8") as f:                json.dump(self.scheduled_tasks, f, ensure_ascii=False, indent=4)        except Exception as e:            logger.error(f"保存计划任务失败: {e}", exc_info=True)    def load_logs(self):        """加载任务执行日志"""        try:            if os.path.exists("./config/task_scheduler_logs.json"):                with open("./config/task_scheduler_logs.json", "r", encoding="utf-8") as f:                    self.task_logs = json.load(f)        except Exception as e:            logger.error(f"加载任务执行日志失败: {e}", exc_info=True)    def save_logs(self):        """保存任务执行日志"""        try:            os.makedirs("./config", exist_ok=True)            with open("./config/task_scheduler_logs.json", "w", encoding="utf-8") as f:                json.dump(self.task_logs, f, ensure_ascii=False, indent=4)        except Exception as e:            logger.error(f"保存任务执行日志失败: {e}", exc_info=True)    def add_task(self, task_info):        """添加计划任务        Args:            task_info (dict): 任务信息，包含以下字段：                - name: 任务名称                - type: 任务类型（"once", "daily", "weekly", "cron")                - schedule: 调度信息（根据任务类型不同而不同）                - ocr_template: OCR模板名称                - folders: 要处理的文件夹列表                - retry_strategy: 失败重试策略（"no_retry", "retry_once", "retry_three_times")                - concurrency_limit: 并发限制        Returns:            str: 任务ID        """        task_id = f"task_{int(time.time() * 1000)}"        task_info["id"] = task_id        task_info["status"] = "running"  # "running" 或 "paused"        task_info["next_execution_time"] = self.calculate_next_execution_time(task_info)        self.scheduled_tasks[task_id] = task_info        self.save_tasks()        self.schedule_task(task_id)        return task_id    def update_task(self, task_id, task_info):        """更新计划任务"""        if task_id in self.scheduled_tasks:            # 取消旧的调度            self.unschedule_task(task_id)            # 更新任务信息            self.scheduled_tasks[task_id].update(task_info)            # 重新计算下次执行时间            self.scheduled_tasks[task_id]["next_execution_time"] = self.calculate_next_execution_time(self.scheduled_tasks[task_id])            self.save_tasks()            # 重新调度任务            if self.scheduled_tasks[task_id]["status"] == "running":                self.schedule_task(task_id)    def delete_task(self, task_id):        """删除计划任务"""        if task_id in self.scheduled_tasks:            # 取消调度            self.unschedule_task(task_id)            # 删除任务            del self.scheduled_tasks[task_id]            self.save_tasks()    def start_task(self, task_id):        """启动计划任务"""        if task_id in self.scheduled_tasks:            self.scheduled_tasks[task_id]["status"] = "running"            self.scheduled_tasks[task_id]["next_execution_time"] = self.calculate_next_execution_time(self.scheduled_tasks[task_id])            self.save_tasks()            self.schedule_task(task_id)    def pause_task(self, task_id):        """暂停计划任务"""        if task_id in self.scheduled_tasks:            self.scheduled_tasks[task_id]["status"] = "paused"            self.unschedule_task(task_id)            self.save_tasks()    def run_task_now(self, task_id):        """立即运行计划任务"""        if task_id in self.scheduled_tasks:            task = self.scheduled_tasks[task_id]            threading.Thread(target=self.execute_task, args=(task,), daemon=True).start()    # ========================= 【调度计算】 =========================    def calculate_next_execution_time(self, task_info):        """计算下次执行时间"""        task_type = task_info["type"]        schedule = task_info["schedule"]        now = datetime.now()        if task_type == "once":            # 一次性任务            execution_time = datetime.strptime(schedule, "%Y-%m-%d %H:%M:%S")            if execution_time > now:                return execution_time.isoformat()            else:                return None        elif task_type == "daily":            # 每天任务            time_parts = schedule.split(":")            if len(time_parts) != 3:                return None            hour = int(time_parts[0])            minute = int(time_parts[1])            second = int(time_parts[2])            execution_time = now.replace(hour=hour, minute=minute, second=second, microsecond=0)            if execution_time <= now:                execution_time += timedelta(days=1)            return execution_time.isoformat()        elif task_type == "weekly":            # 每周任务            weekday = schedule["weekday"]            time_parts = schedule["time"].split(":")            if len(time_parts) != 3:                return None            hour = int(time_parts[0])            minute = int(time_parts[1])            second = int(time_parts[2])            # 计算距离下一个指定星期几的天数            days_until = (weekday - now.weekday()) % 7            if days_until == 0 and now.replace(hour=hour, minute=minute, second=second, microsecond=0) <= now:                days_until = 7            execution_time = now.replace(hour=hour, minute=minute, second=second, microsecond=0) + timedelta(days=days_until)            return execution_time.isoformat()        elif task_type == "cron":            # 自定义Cron表达式（简化处理，仅支持分钟、小时、日期、月份、星期）            parts = schedule.split()            if len(parts) != 5:                return None            try:                minute = int(parts[0])                hour = int(parts[1])                day = int(parts[2])                month = int(parts[3])                weekday = int(parts[4])                # 计算下次执行时间                # 这里简化处理，仅支持固定时间的Cron表达式                execution_time = now.replace(year=now.year, month=month, day=day, hour=hour, minute=minute, second=0, microsecond=0)                if execution_time <= now:                    # 如果是每年一次的任务，下一年执行                    if month == 12 and day == 31:                        execution_time = execution_time.replace(year=now.year + 1)                    else:                        # 否则下一个月执行                        if month == 12:                            execution_time = execution_time.replace(year=now.year + 1, month=1)                        else:                            execution_time = execution_time.replace(month=month + 1)                return execution_time.isoformat()            except Exception:                return None        return None    def schedule_task(self, task_id):        """调度任务"""        task = self.scheduled_tasks.get(task_id)        if not task or task["status"] != "running":            return        next_execution_time = task.get("next_execution_time")        if not next_execution_time:            return        try:            execution_time = datetime.fromisoformat(next_execution_time).timestamp()            # 取消已存在的调度            if task_id in self.scheduler.queue:                for event in self.scheduler.queue:                    if event.argument == task_id:                        self.scheduler.cancel(event)            # 调度新任务            self.scheduler.enterabs(execution_time, 1, self.execute_task, argument=(task,))        except Exception as e:            logger.error(f"调度任务失败: {e}", exc_info=True)    def unschedule_task(self, task_id):        """取消任务调度"""        if task_id in self.scheduler.queue:            for event in self.scheduler.queue:                if event.argument == task_id:                    self.scheduler.cancel(event)    # ========================= 【任务执行】 =========================    def execute_task(self, task):        """执行计划任务"""        task_id = task["id"]        start_time = datetime.now()        log_entry = {            "id": f"log_{int(time.time() * 1000)}",            "task_id": task_id,            "task_name": task["name"],            "start_time": start_time.isoformat(),            "end_time": None,            "status": "running",            "success_count": 0,            "failure_count": 0,            "errors": []        }        try:            # 收集所有要处理的文件            files = []            for folder in task["folders"]:                for root, dirs, filenames in os.walk(folder):                    for filename in filenames:                        # 支持的图片格式                        if filename.lower().endswith((".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff", ".webp")):                            files.append(os.path.join(root, filename))            if not files:                log_entry["errors"].append("没有找到要处理的图片文件")                log_entry["status"] = "failed"            else:                # 预处理参数                argd = self._preprocess_argd(task, files[0])                if not argd:                    log_entry["errors"].append("预处理参数失败")                    log_entry["status"] = "failed"                else:                    # 初始化输出器                    output_list = self._init_output_list(argd)                    if not output_list:                        log_entry["errors"].append("初始化输出器失败")                        log_entry["status"] = "failed"                    else:                        # 运行OCR任务                        success_count, failure_count, errors = self._run_ocr_task(files, argd, output_list, task["concurrency_limit"])                        log_entry["success_count"] = success_count                        log_entry["failure_count"] = failure_count                        log_entry["errors"] = errors                        log_entry["status"] = "success" if failure_count == 0 else "failed"        except Exception as e:            log_entry["status"] = "failed"            log_entry["errors"].append(str(e))        finally:            log_entry["end_time"] = datetime.now().isoformat()            self.task_logs.append(log_entry)            self.save_logs()            # 更新下次执行时间            if task["type"] != "once":                next_execution_time = self.calculate_next_execution_time(task)                if next_execution_time:                    task["next_execution_time"] = next_execution_time                    self.save_tasks()                    self.schedule_task(task_id)            else:                # 一次性任务执行后自动删除                self.delete_task(task_id)    def _preprocess_argd(self, task, path0):        """预处理参数字典"""        try:            # 这里需要根据OCR模板获取对应的参数            # 简化处理，使用默认参数            argd = {                "mission.dirType": "source",                "mission.dir": os.path.dirname(path0),                "mission.datetimeFormat": "%Y-%m-%d_%H-%M-%S",                "mission.fileNameFormat": "%name_%date",                "mission.ignoreBlank": False,                "mission.filesType.txt": True,                "mission.filesType.json": False,                "mission.filesType.html": False,                "mission.filesType.excel": False,                "mission.filesType.word": False,                "mission.filesType.pdf": False,                "mission.filesType.csv": False,                "mission.filesType.clipboard": False,                "mission.filesType.image": False,                "mission.filesType.audio": False,                "mission.filesType.video": False,                "mission.filesType.archive": False,                "mission.filesType.other": False,                "startTimestamp": time.time(),                "startDatetime": datetime.now().strftime("%Y-%m-%d_%H-%M-%S"),            }            # 处理保存目录            if task.get("save_directory"):                argd["mission.dirType"] = "custom"                argd["mission.dir"] = task.get("save_directory", os.path.dirname(path0))            # 处理文件名            start_datetime_user = argd["mission.datetimeFormat"].replace(r"%unix", str(argd["startTimestamp"]))            start_datetime_user = time.strftime(start_datetime_user, time.localtime(argd["startTimestamp"]))            file_name = argd["mission.fileNameFormat"]            file_name = file_name.replace(r"%date", start_datetime_user)            file_name_ele = os.path.basename(os.path.dirname(path0))            file_name = file_name.replace("%name", file_name_ele)            if not allowedFileName(file_name):                logger.error(f"文件名不合法: {file_name}")                return None            argd["mission.fileName"] = file_name            return argd        except Exception as e:            logger.error(f"预处理参数失败: {e}", exc_info=True)            return None    def _init_output_list(self, argd):        """初始化输出器列表"""        try:            output_list = []            output_argd = {                "outputDir": argd["mission.dir"],                "outputDirType": argd["mission.dirType"],                "outputFileName": argd["mission.fileName"],                "startDatetime": argd["startDatetime"],                "ignoreBlank": argd["mission.ignoreBlank"],            }            for key in argd.keys():                if "mission.filesType" in key and argd[key]:                    output_list.append(Output[key[18:]](output_argd))            return output_list        except Exception as e:            logger.error(f"初始化输出器失败: {e}", exc_info=True)            return None    def _run_ocr_task(self, files, argd, output_list, concurrency_limit):        """运行OCR任务"""        success_count = 0        failure_count = 0        errors = []        # 简化处理，不考虑并发限制        for file in files:            try:                msn_info = {                    "onGet": self._on_task_get,                    "argd": argd,                }                msn_list = [{"path": file}]                msn_id = MissionOCR.addMissionList(msn_info, msn_list)                if msn_id.startswith("[Error]"):                    raise Exception(f"添加任务失败: {msn_id}")                # 等待任务完成                while MissionOCR.getMissionStatus(msn_id) != "finished":                    time.sleep(0.1)                # 获取任务结果                result = MissionOCR.getMissionResult(msn_id)                if result["status"] == "success":                    success_count += 1                    # 输出结果                    for o in output_list:                        o.onResult(file, result["data"])                else:                    failure_count += 1                    errors.append(f"处理文件 {file} 失败: {result.get('error', '未知错误')}")            except Exception as e:                failure_count += 1                errors.append(f"处理文件 {file} 失败: {str(e)}")        # 结束输出器        for o in output_list:            try:                o.onEnd()            except Exception as e:                logger.error(f"输出器结束失败: {e}", exc_info=True)                errors.append(f"输出器结束失败: {str(e)}")        return success_count, failure_count, errors    def _on_task_get(self, res):        """任务完成回调"""        pass    # ========================= 【日志管理】 =========================    def get_task_logs(self):        """获取任务执行日志"""        return self.task_logs    def export_logs(self, file_path):        """导出任务执行日志"""        try:            with open(file_path, "w", encoding="utf-8") as f:                json.dump(self.task_logs, f, ensure_ascii=False, indent=4)            return True        except Exception as e:            logger.error(f"导出日志失败: {e}", exc_info=True)            return False    def clear_logs(self):        """清除任务执行日志"""        self.task_logs = []        self.save_logs()    # ========================= 【qml调用python】 =========================    def get_tasks(self):        """获取所有计划任务"""        return list(self.scheduled_tasks.values())    def add_task_qml(self, task_info):        """添加计划任务（qml调用）"""        return self.add_task(task_info)    def update_task_qml(self, task_id, task_info):        """更新计划任务（qml调用）"""        self.update_task(task_id, task_info)    def delete_task_qml(self, task_id):        """删除计划任务（qml调用）"""        self.delete_task(task_id)    def start_task_qml(self, task_id):        """启动计划任务（qml调用）"""        self.start_task(task_id)    def pause_task_qml(self, task_id):        """暂停计划任务（qml调用）"""        self.pause_task(task_id)    def run_task_now_qml(self, task_id):        """立即运行计划任务（qml调用）"""        self.run_task_now(task_id)    def get_task_logs_qml(self):        """获取任务执行日志（qml调用）"""        return self.task_logs    def export_logs_qml(self, file_path):        """导出任务执行日志（qml调用）"""        return self.export_logs(file_path)    def clear_logs_qml(self):        """清除任务执行日志（qml调用）"""        self.clear_logs()